function renderLocalAccess() {
  if(retired||!$('localAccessNotice'))return;
  const access=store.getAccess(), notice=$('localAccessNotice');
  state.access=access; notice.hidden=!access.locked;
  if(access.locked) notice.innerHTML='<span>' + icon('lock') + ' 기기 기록 접근 확인 · 개인 기록은 잠겨 있어요</span><button class="text-button" data-action="local-access">확인하기 ' + icon('arrow-right') + '</button>';
  document.documentElement.style.setProperty('--access-bar',notice.hidden?'0px':notice.offsetHeight+'px');
  const visit=document.querySelector('.top-actions [data-action="visit-new"]');
  if(visit){visit.disabled=access.locked;visit.title=access.locked?'기기 기록 접근을 먼저 확인해주세요':'';}
}
function openLocalAccess() {
  const access=store.getAccess();
  if(!access.locked){toast('현재 계정의 기기 기록을 사용하고 있어요.');return;}
  const description=['storage-unavailable','signed-out'].includes(access.status)?access.reason:access.status==='owner-mismatch'?'다른 계정에 연결된 기기 기록입니다. 방문·관심·회사 조건을 표시하거나 덮어쓰지 않았어요. 원래 계정으로 돌아가거나, 현재 계정의 클라우드 백업을 명시적으로 복원하세요.':'이 기기에 있는 이전 기록의 소유 계정이 아직 확인되지 않았어요. 기록을 자동으로 현재 계정에 붙이지 않았습니다. 본인 기록임을 확인하거나 현재 계정의 클라우드 백업을 복원하세요.';
  const body=note(description,true)+note('지도·공식 가격·분양·모델 검증은 계속 볼 수 있습니다. 잠금 중 조절한 공개 가격 조건은 저장하지 않습니다. 원본 기기 기록과 초안은 삭제하지 않습니다.');
  const claim=access.canClaimLegacy?button('기존 기록 소유 확인','local-claim'):'';
  openModal('기기 기록 보호',body,button('닫기','modal-close')+button('원래 계정으로 전환','local-switch')+claim+button('현재 계정 백업 복원','restore','primary'));
}

function renderNavigation(){ $('navigation').innerHTML=NAV.map(([id,label,i])=>`<button class="nav-button" data-view-link="${id}" ${state.view===id?'aria-current="page"':''}>${icon(i)}<span>${e(label)}</span></button>`).join(''); }
function navigate(view){if(retired)return;if(!NAV.some(n=>n[0]===view))view='board';state.view=view;saveUI({view});renderNavigation();const n=NAV.find(n=>n[0]===view);$('pageTitle').textContent=n[1];$('pageEyebrow').textContent=n[3];document.querySelectorAll('[data-view]').forEach(s=>s.hidden=s.dataset.view!==view);renderCurrent();if(view==='find')ensureMap();window.scrollTo({top:0,behavior:'instant'});}
