function conditionStrip(){return `<div class="condition-strip"><span class="label">우리의 탐색 기준</span><span class="chip">목표 ${money(state.conditions.comfortPriceManWon)}</span><span class="chip">상한 ${money(state.conditions.maxPriceManWon)}</span><span class="chip">${area(state.conditions.minAreaM2)} 이상</span><span class="chip">목적지 ${state.conditions.workplaces.length}곳</span><span class="spacer"></span><button class="text-button" data-action="conditions">${icon('adjustments-horizontal')}조건 바꾸기</button><button class="text-button" data-action="import-v1" ${isLocalLocked()?'disabled':''}>Ver1 조건 가져오기</button><button class="text-button" data-action="import-legacy-v2" ${isLocalLocked()?'disabled':''}>이전 Ver2 조건</button></div>`;}
