    const checked = d?.checkedAt ? new Intl.DateTimeFormat('ko-KR', { timeZone: 'Asia/Seoul', dateStyle: 'short', timeStyle: 'short' }).format(new Date(d.checkedAt)) : '실호출 확인 전';
