function openModelDetails(id) {
  const model = (state.data.backtest?.models || []).find(m => m.id === id);
  if (!model?.metrics) { toast('이 모델의 평가 자료가 아직 없습니다.'); return; }
  const percent = value => number(value) == null ? '보류' : (Number(value) * 100).toFixed(1) + '%';
  const labels = { up: '상승', flat: '보합', down: '하락' };
  const metrics = model.metrics;
  const classRows = Object.entries(metrics.classMetrics || {}).map(([key, m]) => '<tr><td>' + e(labels[key] || key) + '</td><td>' + m.support + '</td><td>' + percent(m.precision) + '</td><td>' + percent(m.recall) + '</td><td>' + Number(m.f1).toFixed(3) + '</td></tr>').join('');
  const matrixLabels = (metrics.classOrder || ['down', 'flat', 'up']).map(k => labels[k] || k);
  const matrixRows = (metrics.confusionMatrix || []).map((row, index) => '<tr><th>' + e(matrixLabels[index]) + '</th>' + row.map(n => '<td>' + e(n) + '</td>').join('') + '</tr>').join('');
  const regions = Object.entries(model.byRegion || {}).map(([code, m]) => '<tr><td>' + e(state.catalog.find(c => c.regionCode === code)?.regionName || code) + '</td><td>' + percent(m.balancedAccuracy) + '</td><td>' + Number(m.macroF1).toFixed(3) + '</td><td>' + Number(m.maePct).toFixed(2) + '%p</td></tr>').join('');
  const effect = model.incrementalEffect;
  const delta = effect ? note('Model ' + effect.vs + ' 대비 공통 ' + effect.commonSamples + '사례 · Macro F1 변화 ' + Number(effect.macroF1Delta).toFixed(3) + ' · 변동률 오차 변화 ' + Number(effect.maeDeltaPct).toFixed(2) + '%p. F1은 커질수록, 오차는 작아질수록 개선입니다.') : note('가격 추세만 쓰는 출발 모델입니다. 항상 상승·가격 유지·단순 추세와 함께 비교합니다.');
  const warning = metrics.downWarnings || {};
  const historicalAssumption = ['C','D','E'].includes(id) ? note('세대수는 현재 카탈로그 값이 과거에도 같았다고 가정했습니다. 과거 변화는 확인되지 않았습니다.', true) : '';
  const body = historicalAssumption + '<p class="muted">평가 ' + model.samples + '사례 · 검증 ' + e(state.data.backtest.verificationLevel || '확인 필요') + '. 같은 월의 단지는 함께 평가하며, 평가할 때 목표 가격이 확정된 과거 사례만 학습합니다.</p>' + delta + '<div class="divider"></div><h3>각 방향은 얼마나 맞았을까?</h3><div class="table-scroll"><table class="transaction-table"><thead><tr><th>방향</th><th>실제 사례</th><th>Precision</th><th>Recall</th><th>F1</th></tr></thead><tbody>' + classRows + '</tbody></table></div><p class="muted" style="font-size:10px;margin-top:10px">Precision은 그 방향이라고 예측했을 때 맞은 비율, Recall은 실제 해당 방향을 찾아낸 비율입니다. 표본이 0인 방향은 신뢰할 성능이 없습니다.</p><div class="divider"></div><div class="grid-two"><div><h3>실제 방향 × 예측 방향</h3><div class="table-scroll"><table class="transaction-table"><thead><tr><th>실제 / 예측</th>' + matrixLabels.map(l => '<th>' + e(l) + '</th>').join('') + '</tr></thead><tbody>' + matrixRows + '</tbody></table></div></div><div><h3>하락 경고</h3><div class="metric-pair"><span>실제 하락을 경고</span><strong>' + e(warning.true ?? '미확보') + '건</strong></div><div class="metric-pair"><span>하락 아닌데 경고</span><strong>' + e(warning.false ?? '미확보') + '건</strong></div>' + note(warning.firstRegimeWarningLeadMonths == null ? '6개월 예측이라고 하락을 6개월 먼저 경고했다는 뜻은 아닙니다. 실제 선행 경고 기간은 아직 입증되지 않았어요.' : '확인한 선행 경고 기간 ' + warning.firstRegimeWarningLeadMonths + '개월') + '</div></div><div class="divider"></div><h3>지역별 성능</h3><div class="table-scroll"><table class="transaction-table"><thead><tr><th>지역</th><th>균형 적중률</th><th>Macro F1</th><th>가격변화 오차</th></tr></thead><tbody>' + regions + '</tbody></table></div><div class="divider"></div><h3>사용한 변수</h3><p class="muted" style="font-size:11px">' + e((model.features || []).map(featureLabel).join(' · ')) + '</p><h3>아직 확보하지 못한 변수</h3><p class="muted" style="font-size:11px">' + e((model.missingFeatures || []).map(featureLabel).join(' · ') || '없음') + '</p>' + note('변수 추가 실험은 예측 도움을 비교합니다. 상관관계가 원인이라는 뜻은 아니며, 같은 시험 자료를 보고 모델을 다시 고르지 않습니다.');
  openModal('Model ' + id + ' · 실제 과거 성능', body, button('닫기', 'modal-close'), true);
}
function openModal(title,body,footer='',wide=false){if(retired)return;focusBeforeModal=document.activeElement;state.modal={};$('modalRoot').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><section class="modal${wide?' wide':''}" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><div><span class="eyebrow">HOMEHUNT · VER 2</span><h2 id="modalTitle">${e(title)}</h2></div><button class="icon-button" data-action="modal-close" aria-label="닫기">${icon('x')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.querySelector('.shell').inert=true;document.querySelector('.sidebar').inert=true;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('.modal input,.modal button')?.focus(),0);}
function closeModal(){placeController?.abort();if($('modalRoot'))$('modalRoot').innerHTML='';state.modal=null;if(document.querySelector('.shell'))document.querySelector('.shell').inert=false;if(document.querySelector('.sidebar'))document.querySelector('.sidebar').inert=false;document.body.style.overflow='';state.chart?.destroy();state.chart=null;focusBeforeModal?.focus?.();}
function openConditions(){const c=state.conditions;openModal('우리의 탐색 조건',`<p class="muted" style="font-size:12px">가격은 만원·억 단위를 자유롭게 입력해요. 적용 뒤 검색 버튼을 누르면 공식 가격을 다시 확인합니다.</p><div class="form-grid"><div class="form-field"><label for="comfortPrice">편안한 목표 가격</label><input id="comfortPrice" value="${money(c.comfortPriceManWon)}" placeholder="6억" inputmode="text"><small>최대 가격과 다르게 자금 비교의 출발점이에요.</small></div><div class="form-field"><label for="maxPrice">최대 가격</label><input id="maxPrice" value="${money(c.maxPriceManWon)}" placeholder="7억 3천만원" inputmode="text"><input class="range" id="priceRange" type="range" min="10000" max="200000" step="500" value="${c.maxPriceManWon}" aria-label="최대 가격 슬라이더"><small>9.3억 · 9억 3천 · 93,000만원 모두 가능해요.</small></div><div class="form-field"><label for="minArea">최소 전용면적</label><div class="field-row"><input id="minArea" value="${c.minAreaM2}" inputmode="decimal"><span>㎡ 이상</span></div><input class="range" id="areaRange" type="range" min="30" max="150" step="1" value="${c.minAreaM2}" aria-label="최소 면적 슬라이더"><small id="areaHelp">${area(c.minAreaM2)} · 공급 평형과 달라요.</small></div><div class="form-field"><label for="minHouseholds">최소 세대수</label><div class="field-row"><input id="minHouseholds" value="${c.minHouseholds??''}" placeholder="제한 없음" inputmode="numeric"><span>세대 이상</span></div></div><div class="form-field"><label for="maxAge">최대 연식</label><div class="field-row"><input id="maxAge" value="${c.maxAgeYears??''}" placeholder="제한 없음" inputmode="numeric"><span>년 이내</span></div></div><div class="form-field"><label>탐색 지역</label><div class="choice-group">${[['seoul','서울'],['gyeonggi','경기']].map(([id,l])=>`<button class="choice" data-condition-region="${id}" aria-pressed="${c.regions.includes(id)}">${l}</button>`).join('')}</div></div></div><div class="divider"></div>${note('역 도보시간·시설 미확인 조건은 충족으로 넘기지 않아요. 실제 통근은 목적지 위치를 확인한 뒤 선택한 후보만 검증해요.')}`,`${button('취소','modal-close')}${button('조건 적용','conditions-save','primary')}`);state.modal.regions=[...c.regions];}
function saveConditions(){const comfort=parseMoneyManWon($('comfortPrice').value),max=parseMoneyManWon($('maxPrice').value),a=number($('minArea').value),h=number($('minHouseholds').value),age=number($('maxAge').value);if(!(comfort>0&&max>=comfort&&a>0)||h<0||age<0||!state.modal.regions.length){toast('목표 ≤ 최대 가격, 면적·세대수·연식을 확인해주세요.');return;}searchController?.abort();++searchEpoch;state.loading=false;state.conditions=persistConditions({...state.conditions,comfortPriceManWon:comfort,maxPriceManWon:max,minAreaM2:a,minHouseholds:h,maxAgeYears:age,regions:state.modal.regions});state.candidates=[];state.searched=false;state.searchError='';closeModal();renderCurrent();updateMap();toast('조건을 적용했어요. 집 찾기에서 다시 검색해주세요.');}
function openRegionSelect(){openModal('어디까지 볼까요?',`<div class="choice-group"><button class="choice" data-region-select="all" aria-pressed="${state.focus==='all'}">서울·경기 전체</button>${FOCUS_REGIONS.map(r=>`<button class="choice" data-region-select="${r.id}" aria-pressed="${state.focus===r.id}">${r.label}</button>`).join('')}</div><div class="divider"></div>${note('전체 범위는 조회할 월·지역이 많아요. 집중 생활권부터 확인하고 필요할 때 넓혀보세요.')}`);}
