function renderDestinations(){const list=state.modal.destinations;$('destinationList').innerHTML=list.length?list.map((d,index)=>`<div class="destination-card"><div class="destination-top"><span class="destination-letter">${String.fromCharCode(65+index)}</span><strong>${e(d.label||d.name||d.address)}</strong><button class="icon-button" data-remove-destination="${index}" aria-label="목적지 삭제">${icon('x')}</button></div><small>${e(d.address)} · ${hasGeo(d)?'위치 확인됨':'위치 재확인 필요'}</small><div class="destination-details" style="margin-top:12px"><div class="form-field"><label>최대 이동시간</label><div class="field-row"><input data-destination-minutes="${index}" value="${d.individualMaxMinutes||d.maxMinutes||60}" inputmode="numeric"><span>분</span></div></div><div class="form-field"><label>주당 방문 횟수</label><input data-destination-weight="${index}" value="${d.daysPerWeek||d.weight||5}" inputmode="decimal"></div><div class="form-field"><label>이동 수단</label><div class="choice-group"><button class="choice" data-destination-mode="${index}:transit" aria-pressed="${!d.modes?.includes('car')}">대중교통</button><button class="choice" data-destination-mode="${index}:car" aria-pressed="${d.modes?.includes('car')||false}">자동차</button></div></div></div></div>`).join(''):empty('목적지를 등록해주세요','아파트 이름이 아니라 회사·건물·주소로 검색할 수 있어요.');}
async function searchPlace(){const query=$('placeQuery').value.trim();if(query.length<2){toast('회사·주소를 두 글자 이상 입력해주세요.');return;}placeController?.abort();placeController=new AbortController();const modal=state.modal;$('placeResults').innerHTML='<div class="progress-box"><span class="spinner"></span> 장소를 검색하고 있어요</div>';try{const result=await services.searchPlaces(query,{signal:placeController.signal});if(state.modal!==modal)return;state.modal.places=result.items||[];$('placeResults').innerHTML=state.modal.places.length?state.modal.places.map((p,i)=>`<button class="place-option" data-place-select="${i}"><strong>${e(String(p.title||p.name).replace(/<[^>]*>/g,''))}</strong><small>${e(p.roadAddress||p.address)}</small></button>`).join(''):empty('검색 결과가 없어요','지역명과 회사명·건물명 일부를 함께 입력해보세요.');}catch(error){if(state.modal!==modal)return;$('placeResults').innerHTML=note(message(error),true);}}
async function selectPlace(index){const modal=state.modal;const p=modal?.places?.[index];if(!p)return;if(state.modal.destinations.length>=4){toast('목적지는 최대 4곳이에요.');return;}let point=hasGeo(p)?{lat:Number(p.lat),lng:Number(p.lng)}:null;if(!point)point=await services.geocodeAddress(p.roadAddress||p.address);if(state.modal!==modal||!state.modal?.destinations)return;if(!point){toast('결과 주소의 위치를 확인하지 못했어요. 다른 결과를 골라주세요.');return;}const id=crypto.randomUUID();state.modal.destinations.push({id,label:String(p.title||p.name).replace(/<[^>]*>/g,''),address:p.roadAddress||p.address,...point,coordinateSource:'naver',locationSource:'naver',individualMaxMinutes:60,daysPerWeek:5,modes:['transit'],required:true});renderDestinations();$('placeResults').innerHTML='';$('placeQuery').value='';}
function saveDestinations(){const destinations=state.modal.destinations;document.querySelectorAll('[data-destination-minutes]').forEach(el=>destinations[Number(el.dataset.destinationMinutes)].individualMaxMinutes=Number(el.value));document.querySelectorAll('[data-destination-weight]').forEach(el=>destinations[Number(el.dataset.destinationWeight)].daysPerWeek=Number(el.value));if(destinations.some(d=>!(d.individualMaxMinutes>0&&d.individualMaxMinutes<=300&&d.daysPerWeek>0&&d.daysPerWeek<=7))){toast('이동시간 1~300분, 주당 횟수 1~7회를 입력해주세요.');return;}destinations.forEach(d=>state.volatileDestinations.set(d.id,{lat:d.lat,lng:d.lng,coordinateSource:d.coordinateSource,locationSource:d.locationSource}));state.conditions=persistConditions({...state.conditions,workplaces:destinations});invalidateCommute();closeModal();renderCurrent();updateMap();toast('목적지를 저장했어요. 기존 통근 판정은 재확인 대상이에요.');}
function openFunding(){const f=state.funding;openModal('두 사람의 자금 시나리오',`<div class="form-grid">${[['cash','가용 현금',f.availableCashWon,'2억'],['reserve','남겨둘 현금',f.cashReserveWon,'3,000만원'],['costs','부대비용 예산',f.additionalCostsWon,'2,000만원'],['existing','기존 월 상환액',f.existingMonthlyWon,'50만원'],['limit','월 상환 한도',f.monthlyPaymentLimitWon,'200만원']].map(([id,label,value,placeholder])=>`<div class="form-field"><label for="fund-${id}">${label}</label><input id="fund-${id}" value="${value==null?'':value===0?'0만원':moneyWon(value)}" placeholder="${placeholder}"></div>`).join('')}<div class="form-field"><label for="fund-rate">예상 대출 금리</label><div class="field-row"><input id="fund-rate" value="${f.rate}" inputmode="decimal"><span>%</span></div></div><div class="form-field"><label for="fund-term">대출 기간</label><div class="field-row"><input id="fund-term" value="${f.term}" inputmode="numeric"><span>년</span></div></div></div><div class="divider"></div>${note('원리금균등 계산입니다. 입력한 금리는 은행의 실제 제시 금리가 아니며, DSR·LTV·대출 승인과 부대비용은 따로 확인해야 해요.')}`,`${button('취소','modal-close')}${button('시나리오 적용','funding-save','primary')}`);}
function saveFunding(){const f={...state.funding};for(const[id,key]of[['cash','availableCashWon'],['reserve','cashReserveWon'],['costs','additionalCostsWon'],['existing','existingMonthlyWon'],['limit','monthlyPaymentLimitWon']])f[key]=parseScenarioMoney($(`fund-${id}`).value);f.rate=Number($('fund-rate').value);f.term=Number($('fund-term').value);if(f.availableCashWon==null||f.rate<0||f.rate>30||!Number.isInteger(f.term)||f.term<1||f.term>50){toast('가용 현금·금리·기간을 확인해주세요.');return;}state.funding=f;closeModal();renderCurrent();toast('이번 Ver2 화면의 시나리오에 적용했어요.');}
async function readWecost(){try{const result=await services.getWecostTarget();const amount=result.snapshot?.targetPriceWon;if(result.status!=='available'||!(amount>0)){toast('WeCost 목표가격을 읽지 못했어요. 연결 상태를 확인해주세요.');return;}openModal('WeCost 목표가격 참고',`<small>현재 WeCost에 저장된 목표 집값</small><div class="detail-price">${moneyWon(amount)}</div>${note('목표 가격 한 필드만 읽었습니다. 이 값은 두 사람의 가용 현금이 아니에요. 자금은 별도로 입력하세요.')}`,`${button('닫기','modal-close')}${button('Ver2 목표에 적용','wecost-apply','primary')}`);state.modal.wecostPrice=amount;}catch(error){toast(message(error));}}
function openVisit(record=null,candidate=null){if(isLocalLocked()){openLocalAccess();return;}const c=record||candidate||{};openModal(record?'방문 기록 수정':'다녀온 집 기록',`<div class="form-grid"><div class="form-field full"><label for="visitName">단지명</label><input id="visitName" value="${e(c.name||'')}" placeholder="아파트 이름"></div><div class="form-field full"><label for="visitAddress">주소</label><input id="visitAddress" value="${e(c.address||'')}" placeholder="방문한 집의 주소"></div><div class="form-field"><label for="visitDate">방문일</label><input id="visitDate" value="${e(c.visitDate||new Date().toLocaleDateString('sv-SE'))}" placeholder="날짜 선택" readonly></div><div class="form-field"><label for="visitPrice">현장 확인 가격</label><input id="visitPrice" value="${c.askingPrice?money(c.askingPrice):''}" placeholder="6억 5천만원"></div><div class="form-field"><label for="visitArea">전용면적</label><div class="field-row"><input id="visitArea" value="${c.areaM2||candidateArea(c)||''}" inputmode="decimal"><span>㎡</span></div></div><div class="form-field"><label for="visitFloor">층</label><input id="visitFloor" value="${c.floor||''}" inputmode="numeric"></div><div class="form-field full"><label>거래 유형</label><div class="choice-group">${['매매','전세','월세'].map(d=>`<button class="choice" data-visit-deal="${d}" aria-pressed="${(c.dealType||'매매')===d}">${d}</button>`).join('')}</div></div><div class="form-field"><label for="visitPros">좋았던 점</label><textarea id="visitPros" rows="3">${e(c.pros||'')}</textarea></div><div class="form-field"><label for="visitCons">아쉬웠던 점</label><textarea id="visitCons" rows="3">${e(c.cons||'')}</textarea></div><div class="form-field full"><label for="visitMemo">둘의 메모</label><textarea id="visitMemo" rows="3">${e(c.memo||'')}</textarea></div></div>`,`${record?button('기록 삭제','visit-delete','danger'):''}${button('취소','modal-close')}${button('방문 저장','visit-save','primary')}`);state.modal.visitOriginal=record;state.modal.visitCandidate=c;state.modal.dealType=c.dealType||'매매';if(window.flatpickr)flatpickr($('visitDate'),{locale:'ko',dateFormat:'Y-m-d',disableMobile:true,monthSelectorType:'static',defaultDate:$('visitDate').value});else{$('visitDate').readOnly=false;$('visitDate').placeholder='YYYY-MM-DD';}}
function saveVisit(){const c=state.modal.visitCandidate;const name=$('visitName').value.trim(),address=$('visitAddress').value.trim(),date=$('visitDate').value,amount=parseMoneyManWon($('visitPrice').value),a=Number($('visitArea').value);if(!name||!address||!/^\d{4}-\d{2}-\d{2}$/.test(date)||!(a>0)||!(amount>0)){toast('단지명·주소·방문일·가격·면적을 확인해주세요.');return;}try{store.saveVisit({...c,id:state.modal.visitOriginal?.id||crypto.randomUUID(),name,address,visitDate:date,askingPrice:amount,areaM2:a,floor:Number($('visitFloor').value)||0,dealType:state.modal.dealType,visitedBy:['성우','소희'],pros:$('visitPros').value,cons:$('visitCons').value,memo:$('visitMemo').value,status:c.status||'검토',tags:c.tags||[]},{expectedRecord:state.modal.visitOriginal});state.shared=store.getShared();closeModal();state.recordType='visits';navigate('records');toast('방문 기록을 저장했어요.');}catch(error){toast(message(error));}}
async function openDetail(c) {
  if (retired || !c) return;
  state.detail = c; state.facilities = null;
  const routes = (c.commuteEvaluations || []).map(({ d, route }) => '<div class="metric-pair"><span>' + e(d.label || d.address) + '</span><strong>' + (route ? Math.round(route.durationMinutes) + '분' : '경로 미확인') + '</strong></div>').join('');
  const facts = '<div class="detail-facts"><div><span>세대수</span><strong>' + (c.households ? c.households + '세대' : '확인 필요') + '</strong></div><div><span>준공연도</span><strong>' + (c.builtYear ? c.builtYear + '년' : '확인 필요') + '</strong></div><div><span>주차·난방·동수</span><strong id="facilityStatus">공식 상세 확인 전</strong></div><div><span>최근 가격 기준월</span><strong>' + e(c.bestArea?.latestMonth || c.priceObservedAt || '확인 필요') + '</strong></div></div>';
  const links = '<div class="field-row">' + button('지도 위치 확인', 'detail-locate') + button('공식 시설 확인', 'detail-facilities') + '<a class="button" target="_blank" rel="noopener noreferrer" href="https://map.naver.com/p/search/' + encodeURIComponent(c.name + ' ' + c.address) + '">네이버 지도 ' + icon('external-link') + '</a><a class="button" target="_blank" rel="noopener noreferrer" href="https://new.land.naver.com/search?query=' + encodeURIComponent(c.name) + '">현재 매물 확인 ' + icon('external-link') + '</a></div>';
  const body = '<small>' + e(c.address) + '</small><div class="detail-price" style="margin-top:10px">' + money(price(c) || c.askingPrice) + '</div><small>' + (price(c) ? '조회·저장 실거래 기준' : '가격 확인 필요 또는 현장 확인가') + ' · ' + area(candidateArea(c) || c.areaM2) + '</small>' + axisCards(c) + facts + personalParkingHtml(c) + '<div id="facilityDetail"></div><div class="divider"></div>' + links + (routes ? '<div class="divider"></div>' + routes : '');
  openModal(c.name, body, button(isFavorite(c) ? '관심 해제' : '관심 저장', 'detail-favorite') + button('방문 기록', 'detail-visit') + button('실거래·전망', 'detail-market', 'primary'), true);
}

function facilityMarkup(info) {
  if (!info.complexMatchConfirmed) return note(info.relatedComplex?.scopeLabel ? info.relatedComplex.scopeLabel + ' 자료입니다. 개별 단지 시설로 대신 판단하지 않습니다.' : '공식 단지와 정확히 대조하지 못했어요. 누락 시설은 0이 아니라 미확인으로 표시합니다.', true);
  const facts = [['주차',info.parking?.totalSpaces,'대'],['세대당 주차',info.parking?.spacesPerHousehold,'대'],['난방',info.heatingType,''],['동수',info.buildingCount,'동'],['승강기',info.elevatorCount,'대'],['최고층',info.highestFloor,'층'],['사용승인',info.approvalDate,''],['지상 충전기',info.groundEvChargers,'대'],['지하 충전기',info.undergroundEvChargers,'대']];
  const detail = '<div class="detail-facts" style="margin-top:15px">' + facts.map(([label,value,unit]) => '<div><span>' + e(label) + '</span><strong>' + (value == null ? '미확인' : e(value) + unit) + '</strong></div>').join('') + '</div>';
  return detail + (info.welfareFacilities ? '<p class="muted" style="font-size:11px;margin-top:15px">공용시설 · ' + e(info.welfareFacilities) + '</p>' : '') + '<p class="muted" style="font-size:10px;margin-top:12px">국토부 K-apt · 확인 ' + e(info.observedAt?.slice(0,10) || '미확인') + '. 개인 확인 주차는 별도로 유지합니다.</p>';
}

function openSupply(n){openModal(n.title,`<small>${e(n.sourceLabel||n.source)} · 공고 ${e(n.announcementDate)}</small><div class="divider"></div><div class="detail-facts"><div><span>최고 분양가</span><strong>${n.maxPriceManWon?money(n.maxPriceManWon):'공고문 확인'}</strong></div><div><span>공급 세대</span><strong>${n.totalUnits?`${n.totalUnits}세대`:'공고문 확인'}</strong></div><div><span>공고 표기 면적</span><strong>${n.minAreaM2?`${n.minAreaM2}㎡ · 전용면적 원문 확인`:'미공개'}</strong></div><div><span>신혼 대상 근거</span><strong>${e(n.targetGroups?.join(' · ')||'공고 원문 확인')}</strong></div></div><div class="divider"></div>${(n.schedules||[]).map(s=>`<div class="metric-pair"><span>${e(s.label||s.kind)}</span><strong>${e(s.startDate)} ~ ${e(s.endDate)}</strong></div>`).join('')}${note('분양가·입주 시점·계약금·중도금·잔금 일정과 주변 동일 면적 실거래를 함께 확인하세요. 신청 자격과 실제 접수는 공식 원문에서 확인합니다.')}<div class="divider"></div><h3>신청 전 확인</h3><p class="muted" style="font-size:12px">무주택 여부 · 거주기간 · 청약통장 · 혼인기간 · 소득·자산 · 특별공급 이력 · 계약 자금. 이 정보만으로 당첨 확률을 만들지 않습니다.</p>`,`${button('닫기','modal-close')}<a class="button primary" href="${e(safeExternal(n.sourceUrl))}" target="_blank" rel="noopener noreferrer">공고·신청 원문 ${icon('external-link')}</a>`);}
function exportRecords(){const blob=new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),snapshot:store.getBackupSnapshot()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`homehunt-records-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('개인 기록 백업을 저장했어요.');}
function importRecords(){openModal('기록 파일 가져오기',`<p class="muted">먼저 JSON 파일을 선택하면 파일 내용을 확인한 뒤 공유 기록을 파일의 기록으로 교체합니다. 현재 기록을 먼저 JSON으로 백업해주세요. Ver2 탐색 조건은 유지합니다.</p><label class="button subtle" for="backupFile">${icon('file-upload')}JSON 파일 선택</label><input type="file" id="backupFile" accept="application/json,.json" hidden><div id="importPreview" style="margin-top:15px"></div>`,`${button('취소','modal-close')}${button('확인한 기록 가져오기','import-confirm','primary')}`);state.modal.expectedFingerprint=store.getSharedFingerprint();}
async function handleAction(action){if(retired)return;const [type,...parts]=action.split(':');const id=parts.join(':');try{if(isLocalLocked()&&lockedActions.has(type)){openLocalAccess();return;}if(type.startsWith('go-')){navigate(type.slice(3));return;}switch(type){case'local-access':openLocalAccess();break;case'local-claim':openModal('이 기기의 기록 소유 확인',note('이 기기에 남아 있는 방문·관심·회사 입력이 현재 로그인한 계정의 기록인지 확인해주세요. 확인하면 원본 데이터는 그대로 두고 소유 표시만 연결합니다. 다른 사람의 기록이라면 원래 계정으로 전환하거나 본인 클라우드 백업을 복원해주세요.',true),`${button('취소','modal-close')}${button('내 기록이 맞아요','local-claim-confirm','primary')}`);break;case'local-claim-confirm':store.claimLegacy();state.access=store.getAccess();state.shared=store.getShared();state.conditions=store.getConditions();closeModal();renderCurrent();toast('확인한 기기 기록을 열었어요. 이전 Ver2 회사 조건은 별도로 가져와야 합니다.');break;case'local-switch':await services.signOut();break;case'import-legacy-v2':state.conditions=store.importLegacyV2Conditions();state.candidates=[];state.searched=false;state.volatileDestinations.clear();renderCurrent();toast('이전 Ver2 조건을 명시적으로 가져왔어요. 회사 위치는 다시 확인해주세요.');break;case'model-detail':openModelDetails(id);break;case'conditions':openConditions();break;case'conditions-save':saveConditions();break;case'import-v1':state.conditions=store.importV1Conditions();state.candidates=[];state.searched=false;renderCurrent();toast('Ver1 조건을 Ver2로 가져왔어요. 원래 조건은 그대로예요.');break;case'destinations':openDestinations();break;case'destinations-save':saveDestinations();break;case'supply-budget':state.supplyBudget=!state.supplyBudget;renderSupply();break;case'supply-unknown':state.supplyIncludeUnknown=!state.supplyIncludeUnknown;renderSupply();break;case'place-search':await searchPlace();break;case'place-address':await searchAddress();break;case'region-select':openRegionSelect();break;case'search':await runSearch();break;case'cancel-search':searchController?.abort();break;case'toggle-list':state.listCollapsed=!state.listCollapsed;$('finderBody')?.classList.toggle('list-collapsed',state.listCollapsed);state.map?.resize();break;case'map-fit':updateMap(true);break;case'map-zoom-in':if(state.mapReady)state.map.map.setZoom(state.map.map.getZoom()+1);break;case'map-zoom-out':if(state.mapReady)state.map.map.setZoom(state.map.map.getZoom()-1);break;case'map-more':await hydrateMapCoordinates(searchEpoch,50);break;case'funding':openFunding();break;case'funding-save':saveFunding();break;case'wecost':await readWecost();break;case'wecost-apply':state.conditions=persistConditions({...state.conditions,comfortPriceManWon:state.modal.wecostPrice/10000,maxPriceManWon:Math.max(state.modal.wecostPrice/10000,state.conditions.maxPriceManWon)});closeModal();renderCurrent();break;case'detail':openDetail(findCandidate(id));break;case'favorite':toggleFavorite(findCandidate(id));break;case'compare':toggleCompare(findCandidate(id));break;case'market':state.history=null;state.exactArea=null;await loadHistory(findCandidate(id),{months:12});break;case'market-search':showSuggestions($('marketQuery').value);break;case'cancel-history':historyController?.abort();break;case'commute':await verifyOne(findCandidate(id));break;case'commute-confirm':await confirmCommute();break;case'visit-new':openVisit();break;case'visit-edit':openVisit(state.shared.visits.find(v=>v.id===id));break;case'visit-save':saveVisit();break;case'visit-delete':{const v=state.modal.visitOriginal;openModal('방문 기록 삭제',`<p>${e(v.name)} 방문 기록을 삭제할까요?</p>`,`${button('취소','modal-close')}${button('삭제','visit-delete-confirm','danger')}`);state.modal.deleteVisit=v;break;}case'visit-delete-confirm':store.deleteVisit(state.modal.deleteVisit.id,{expectedRecord:state.modal.deleteVisit});state.shared=store.getShared();closeModal();renderRecords();toast('방문 기록을 삭제했어요.');break;case'detail-market':{const c=state.detail;closeModal();state.history=null;state.exactArea=null;await loadHistory(c,{months:12});break;}case'detail-favorite':toggleFavorite(state.detail);break;case'detail-visit':openVisit(null,state.detail);break;case'detail-locate':await locateCandidate(state.detail);updateMap(true);toast('정확한 주소로 지도 위치를 확인했어요.');break;case'detail-facilities':{const c=state.detail;const modal=state.modal;$('facilityStatus').textContent='공식 자료 확인 중';const f=await services.fetchFacilities(c);if(state.modal!==modal)return;$('facilityStatus').textContent=f.status==='matched'||f.status==='verified'?'공식 자료 확인':'단지 대조·정보 확인 필요';$('facilityDetail').innerHTML=facilityMarkup(f);state.facilities=f;break;}case'modal-close':closeModal();break;case'health':{toast('공급자 경로를 호출하지 않고 서버 상태를 확인해요.');state.connection=await services.getConnectionState();renderConnection();break;}case'export-records':exportRecords();break;case'import-records':importRecords();break;case'import-confirm':if(!state.modal.importSnapshot){toast('JSON 파일을 먼저 선택해주세요.');return;}store.applyBackupSnapshot(state.modal.importSnapshot,{expectedFingerprint:state.modal.expectedFingerprint});state.shared=store.getShared();closeModal();renderCurrent();toast('파일의 공유 기록으로 교체했어요. Ver2 조건은 유지됩니다.');break;case'backup':{const result=await services.backupRecords(store);toast(result.note||'현재 계정에 기록을 백업했어요.');break;}case'restore':openModal('계정 기록 가져오기',note(`${services.getSessionState().user?.displayName||'현재 로그인한 계정'}의 백업으로 이 기기의 공유 기록을 교체합니다. 현재 기록을 먼저 JSON으로 백업해주세요. 버전별 탐색 조건은 보존합니다.`),`${button('취소','modal-close')}${button('백업 불러오기','restore-confirm','primary')}`);break;case'restore-confirm':{const result=await services.restoreRecords(store);state.shared=store.getShared();closeModal();renderCurrent();toast(result.empty?'계정에 저장된 백업이 없어요. 현재 기록은 유지했습니다.':result.note||'현재 계정 백업의 공유 기록을 가져왔어요.');break;}}}
catch(error){toast(message(error));}}
on(document,'click',event=>{if(retired)return;const t=event.target.closest('button,a');if(!t){if(event.target.dataset.backdrop)closeModal();return;}if(t.dataset.viewLink){navigate(t.dataset.viewLink);return;}if(t.dataset.action){handleAction(t.dataset.action);return;}if(t.dataset.region){state.focus=t.dataset.region;navigate('find');state.map?.moveTo(...FOCUS_REGIONS.find(r=>r.id===state.focus).center,12);return;}if(t.dataset.regionSelect){state.focus=t.dataset.regionSelect;closeModal();renderCurrent();updateMap();return;}if(t.dataset.detail){openDetail(findCandidate(t.dataset.detail));return;}if(t.dataset.favorite){toggleFavorite(findCandidate(t.dataset.favorite));return;}if(t.dataset.scope){state.scope=t.dataset.scope;renderFindResults();updateMap();return;}if(t.dataset.recordType){state.recordType=t.dataset.recordType;renderRecords();return;}if(t.dataset.historySelect){state.history=null;state.exactArea=null;loadHistory(findCandidate(t.dataset.historySelect),{months:12});return;}if(t.dataset.historyMonths){loadHistory(state.marketCandidate,{months:Number(t.dataset.historyMonths)});return;}if(t.dataset.deal){state.dealType=t.dataset.deal;state.exactArea=null;renderMarket();return;}if(t.dataset.area){state.exactArea=Number(t.dataset.area);renderMarket();return;}if(t.dataset.supplyType){state.supplyType=t.dataset.supplyType;renderSupply();return;}if(t.dataset.supplyFavorite){if(isLocalLocked()){openLocalAccess();return;}const id=t.dataset.supplyFavorite;const items=state.shared.supplyFavorites.includes(id)?state.shared.supplyFavorites.filter(x=>x!==id):[...state.shared.supplyFavorites,id];store.saveSharedField('supplyFavorites',items);state.shared=store.getShared();renderSupply();return;}if(t.dataset.supplyDetail){openSupply(state.data.supply.notices.find(n=>n.id===t.dataset.supplyDetail));return;}if(t.dataset.conditionRegion){const id=t.dataset.conditionRegion;state.modal.regions=state.modal.regions.includes(id)?state.modal.regions.filter(v=>v!==id):[...state.modal.regions,id];t.setAttribute('aria-pressed',String(state.modal.regions.includes(id)));return;}if(t.dataset.placeSelect){selectPlace(Number(t.dataset.placeSelect));return;}if(t.dataset.removeDestination){state.modal.destinations.splice(Number(t.dataset.removeDestination),1);renderDestinations();return;}if(t.dataset.destinationMode){const[index,mode]=t.dataset.destinationMode.split(':');state.modal.destinations[Number(index)].modes=[mode];renderDestinations();return;}if(t.dataset.visitDeal){state.modal.dealType=t.dataset.visitDeal;document.querySelectorAll('[data-visit-deal]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.visitDeal===state.modal.dealType)));return;}});
on(document,'input',event=>{if(retired)return;const t=event.target;if(t.id==='marketQuery')showSuggestions(t.value);if(t.id==='finderQuery'){state.query=t.value;renderFindResults();updateMap();}if(t.id==='supplyQuery'){state.supplyQuery=t.value;const pos=t.selectionStart;renderSupply();$('supplyQuery').focus();$('supplyQuery').setSelectionRange(pos,pos);}if(t.id==='priceRange')$('maxPrice').value=money(Number(t.value));if(t.id==='maxPrice'){const n=parseMoneyManWon(t.value);if(n)$('priceRange').value=n;}if(t.id==='areaRange'){$('minArea').value=t.value;$('areaHelp').textContent=area(t.value);}if(t.id==='minArea'){$('areaRange').value=Number(t.value);$('areaHelp').textContent=area(t.value);}});
on(document,'change',async event=>{if(retired)return;if(event.target.id!=='backupFile')return;const modal=state.modal;if(!modal)return;const fileEpoch=(modal.fileEpoch||0)+1;modal.fileEpoch=fileEpoch;try{const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw new Error('백업 파일은 5MB 이하로 선택해주세요.');const raw=JSON.parse(await file.text());if(retired||state.modal!==modal||modal.fileEpoch!==fileEpoch)return;const snapshot=raw.snapshot||raw;state.modal.importSnapshot=snapshot;$('importPreview').innerHTML=note(`방문 ${snapshot.visits?.length||0}건 · 관심 ${snapshot.shortlist?.length||0}건 · 분양 관심 ${snapshot.supplyFavorites?.length||0}건. 기존 백업 계약으로 확인 후 가져옵니다.`);}catch(error){if(retired||state.modal!==modal||modal.fileEpoch!==fileEpoch)return;state.modal.importSnapshot=null;$('importPreview').innerHTML=note(message(error),true);}});
on(document,'keydown',event=>{if(retired)return;if(!state.modal)return;if(event.key==='Escape'){event.preventDefault();closeModal();}if(event.key==='Tab'){const nodes=[...document.querySelectorAll('.modal button,.modal input:not([hidden]),.modal textarea,.modal a')].filter(el=>!el.disabled&&el.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if(event.key==='Enter'&&event.target.id==='placeQuery'){event.preventDefault();searchPlace();}});
on($('globalSearch'),'submit',event=>{if(retired)return;event.preventDefault();state.query=$('globalQuery').value.trim();navigate('market');$('marketQuery').value=state.query;showSuggestions(state.query);});
on($('accountButton'),'click',()=>{const current=services.getSessionState();openModal(current.user?'계정과 기록':'계정 연결',current.user?`<p>${e(current.user.displayName||'로그인한 사용자')}</p>${note('기록 백업·복원은 직접 선택할 때만 실행합니다. 다른 계정의 백업을 자동으로 합치지 않습니다.')}`:note('온라인 가격·통근 검색과 계정 백업은 로그인과 회원 권한이 필요해요. 기록은 이 기기에 유지되지만 승인된 회원만 화면을 열 수 있어요.'),current.user?`${button('닫기','modal-close')}${button('계정에 백업','backup')}${button('로그아웃','account-signout')}`:`${button('취소','modal-close')}${button('Google로 연결','account-signin','primary')}`);});
on(document,'click',async event=>{if(retired)return;if(retired)return;const action=event.target.closest('button')?.dataset.action;if(action==='account-signin'||action==='account-signout'){try{if(action==='account-signin')await services.signIn();else await services.signOut();closeModal();}catch(error){toast(message(error));}}});
const stopStore = store.subscribe(({shared,conditions,ui,access})=>{if(retired)return;const previouslyLocked=state.access?.locked;state.access=access||store.getAccess();if(state.access.locked&&!previouslyLocked){searchController?.abort();historyController?.abort();searchEpoch++;historyEpoch++;state.marketCandidate=null;state.history=null;state.detail=null;state.facilities=null;state.volatileDestinations.clear();state.ui={...ui,compareIds:[]};if(state.modal)closeModal();}const safeConditions=state.access.locked&&previouslyLocked?state.conditions:conditions;const changed=JSON.stringify(state.conditions)!==JSON.stringify(safeConditions);state.shared=shared;state.conditions=safeConditions;state.ui=state.access.locked?state.ui:ui;if(changed){searchController?.abort();++searchEpoch;state.loading=false;state.searched=false;state.candidates=[];invalidateCommute();}if(!state.modal&&!state.loading&&!state.historyLoading){renderCurrent();updateMap();}},{emitCurrent:false});
const stopSession = services.subscribeSession(session=>{if(retired)return;const uid=session.user?.uid||null;if(sessionUid!==null&&uid!==sessionUid){searchController?.abort();historyController?.abort();searchEpoch++;historyEpoch++;state.loading=false;state.historyLoading=false;state.candidates=[];state.history=null;state.searched=false;state.volatileDestinations.clear();state.funding={...state.funding,availableCashWon:null};if(state.modal)closeModal();}sessionUid=uid;$('accountButton').innerHTML=`${icon('user-circle')}<span>${e(session.user?.displayName?.split(' ')[0]||'계정 연결')}</span>`;});
on(window,'resize',()=>{renderLocalAccess();state.map?.resize();});
async function init(){navigate(state.view);const results=await Promise.allSettled([services.loadCatalog(),services.loadPublicData()]);if(retired||!getMember())return;if(results[0].status==='fulfilled')state.catalog=results[0].value.apartments||results[0].value;if(results[1].status==='fulfilled')state.data=results[1].value;if(results.some(r=>r.status==='rejected'))toast('일부 공개 자료를 읽지 못했어요. 연결 상태에서 확인하세요.');$('bootStatus').hidden=true;applyPublicPrices();renderCurrent();}
registerPrivateCleanup(() => {
  retired = true; lifetimeEvents.abort(); ++searchEpoch; ++historyEpoch;
  searchController?.abort(); historyController?.abort(); placeController?.abort();
  stopStore?.(); stopSession?.(); store.dispose(); services.destroyServices?.();
  clearTimeout(toastTimer); state.chart?.destroy();
  for (const input of document.querySelectorAll('input')) input._flatpickr?.destroy();
  state.map?.clearCandidateMarkers(); state.map?.clearContextRecords(); state.map?.clearCompanyLocation(); state.map?.clearSearchLocation();
  if(state.map?.map&&window.naver?.maps?.Event) window.naver.maps.Event.clearInstanceListeners?.(state.map.map);
  state.map=null; state.mapReady=false; state.volatileDestinations.clear();
  state.candidates=[]; state.pending=[]; state.shared={visits:[],shortlist:[],supplyFavorites:[],parkingObservations:[]}; state.conditions={workplaces:[]}; state.history=null; state.detail=null; state.modal=null; state.funding={};
  document.body.style.overflow='';
});
init().catch(error=>{if(retired)return;if($('bootStatus'))$('bootStatus').hidden=true;toast(message(error));});
